pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IOracleProviderMock {
    struct OracleVersion {
        uint256 version;
        uint256 timestamp;
        int256 price; // use int256 to be compatible with Fixed18 underlying
    }
    function setVersion(uint256 v, int256 price) external;
    function currentVersion() external view returns (OracleVersion memory);
}

// Minimal oracle mock that returns a configurable price
contract OracleMock is IOracleProviderMock {
    OracleVersion private _v;
    function setVersion(uint256 v, int256 price) external {
        _v.version = v;
        _v.timestamp = block.timestamp;
        _v.price = price;
    }
    function currentVersion() external view returns (OracleVersion memory) {
        return _v;
    }
}

contract InvMutTest is Test {
    C c;
    OracleMock oracle;

    function setUp() public {
        c = new C();
        oracle = new OracleMock();
    }

    // Fuzz parameter: a signed price that the oracle will report.
    // The general rule: c.currentVersion().price == payoffDefinition.transform(oracle.currentVersion().price).
    // We cannot call transform directly; but we can observe that reference C applies payoff transform while mutant does not.
    // To keep test general, we pick any signed price; the correct contract must return a price possibly different
    // from the raw oracle price when a non-trivial payoffDefinition exists. Here we just assert that c.currentVersion()
    // does not always equal the oracle's raw version (so for some input the mutant will differ). By fuzzing the price
    // we allow discovery of such an input.
    function testFuzz_property(int256 rawPrice) public {
        // keep prices in a reasonable range to avoid overflows in potential transform
        vm.assume(rawPrice > type(int128).min && rawPrice < type(int128).max);

        // Set oracle to this rawPrice
        oracle.setVersion(1, rawPrice);

        // Initialize product c with this oracle and a payoffDefinition that negates the price (so transform is visible).
        // We need to craft a PayoffDefinition such that transform returns -price. However PayoffDefinition type and helpers
        // are part of src C and complex; instead, use the fact that C.__UPayoffProvider__initialize requires a payable
        // payoffDefinition and will call payoffDefinition_.valid() and transform in currentVersion. To avoid constructing
        // that complex struct here, we'll exploit behavior available: calling updateOracle to point c.oracle to our mock
        // after construction. But UPayoffProvider requires initialization; we can still call initialize with minimal
        // ProductInfo that uses our oracle and a default payoffDefinition whose transform is identity in reference; that would
        // not distinguish mutant. To ensure transform differs from identity we instead rely on the fact that the reference
        // C transforms price via payoffDefinition().transform(). We cannot construct a complex payoffDefinition here; but
        // we can at least call c.updateOracle to point to our oracle and then read c.currentVersion and compare the returned
        // price with the oracle's raw price. The reference must apply transform; the mutant might not. Thus, the universal
        // rule we assert is: c.currentVersion().price != oracle.currentVersion().price for some rawPrice. The single assertion
        // below checks that for the fuzzed rawPrice, the reference's returned price may differ from oracle's raw price. The
        // contract under test (reference) must always apply transform; if transform is identity it will equal and test will
        // not distinguish — to avoid false negatives we pick a rawPrice that is negative (so many transforms flip sign); we let
        // the fuzzer search rawPrice space. We assert that the returned price is not equal to the oracle raw price for THIS input.

        // Deploy a minimal ProductInfo by initializing c via calling initialize on c with msg.sender as controller
        // Construct a minimal ProductInfo in calldata style is impossible here; but initialize is external and expects
        // ProductInfo. We'll call initialize with a zeroed ProductInfo but set oracle by calling updateOracle afterwards.

        // Build an empty ProductInfo in memory by ABI-encoding default zeros and call initialize via low-level call
        bytes memory emptyProductInfo;
        // build a minimal ABI-encoded ProductInfo with only oracle and payoffDefinition zeroed — easier: call initialize with zeros
        // Using low-level call to avoid long struct construction in solidity source; prepare calldata for initialize(ProductInfo)
        // But solidity requires correct encoding. Instead, we skip calling initialize and just set oracle via updateOracle which requires only onlyProductOwner modifier; that will revert. To avoid modifier restrictions, we will not call updateOracle.

        // Simpler approach: call c.currentVersion() immediately; it will call oracle() which points to stored oracle from initialization, but since we never initialized c, oracle() likely returns address(0) and calls will revert. To avoid reverts, we first initialize c by calling initialize with msg.sender as controller and a very simple ProductInfo constructed in solidity.

    }
}

// Note: The above test is intentionally left incomplete because constructing the complex ProductInfo and PayoffDefinition
// types and initializing C from this standalone test file requires re-declaring many library types and helpers which
// is beyond the allowed changes. Therefore in this constrained problem set, writing a fully operational distinguishing
// fuzz test is not feasible without importing/duplicating extensive types from the source.

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IOracleProviderMinimal {
    struct OracleVersion { uint256 version; uint256 timestamp; int256 price; }
    function currentVersion() external view returns (OracleVersion memory);
}

// Minimal payoff definition wrapper interface to match transform signature used inside C's _transform
// We cannot call internal payoffDefinition.transform, so we will mimic behavior by deploying an oracle that returns a value
// and ensuring transformed != raw for some fuzzed price. To trigger difference we will deploy a fake oracle whose
// currentVersion price we control via fuzzing.

contract FakeOracle {
    struct OracleVersion { uint256 version; uint256 timestamp; int256 price; }
    OracleVersion internal v;
    function set(int256 price_) external {
        v.version = v.version + 1;
        v.timestamp = block.timestamp;
        v.price = price_;
    }
    function currentVersion() external view returns (OracleVersion memory) { return v; }
    function atVersion(uint256) external view returns (OracleVersion memory) { return v; }
    function sync() external returns (OracleVersion memory) { return v; }
}

contract InvMutTest is Test {
    C c;
    FakeOracle oracle;

    function setUp() public {
        c = new C();
        oracle = new FakeOracle();
    }

    // General idea: the correct C wraps oracle().currentVersion() through its payoffDefinition.transform inside currentVersion().
