}

// A minimal mock oracle that returns a predictable OracleVersion for any id.
contract MockOracle is IOracleProviderMinimal {
    function atVersion(uint256 oracleVersion) external pure returns (OracleVersion memory) {
        return OracleVersion({ version: oracleVersion, timestamp: block.timestamp, price: int256(int256(oracleVersion) * 2 + 1) });
    }
}

contract InvMutTest is Test {
    C c;
    MockOracle oracle;

    function setUp() public {
        c = new C();
        oracle = new MockOracle();
