        // struct ProductInfo { string name; string symbol; PayoffDefinition payoffDefinition; IOracleProvider oracle; UFixed18 maintenance; UFixed18 fundingFee; UFixed18 makerFee; UFixed18 takerFee; UFixed18 positionFee; UFixed18 makerLimit; JumpRateUtilizationCurve utilizationCurve; }
        // Encode payoffDefinition as (uint8,uint8,bytes30)
        bytes memory payoffDefEncoded = abi.encode(payoffType, payoffDirection, emptyPayoffData);

        bytes memory productInfoEncoded = abi.encode(
            string(name),
            string(symbol),
            // payoffDefinition: will be decoded by callee as PayoffDefinition
            // but we must ensure encoding matches calldata expectations; encode bytes as tuple
            // Using abi.encode for the whole ProductInfo
            // We cannot directly construct the complex types exactly; instead use a two-step: encode a tuple matching the ABI of initialize(ProductInfo)
            // Construct a JumpRateUtilizationCurve struct compatible tuple: (PackedFixed18 minRate, PackedFixed18 maxRate, PackedFixed18 targetRate, PackedUFixed18 targetUtilization)
            // We place a placeholder and rely on abi.encode to pack correctly.
            // However to ensure proper types, we will build the full ProductInfo as per expected ABI types.
            // Build a tuple: (string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(uint256,uint256,uint256,uint256))
            name,
            symbol,
            abi.decode(abi.encode(payoffType, payoffDirection, emptyPayoffData), (bytes)),
            oracleAddr,
            maintenance_val,
            fundingFee,
            makerFee,
            takerFee,
            positionFee,
            makerLimit,
            // utilizationCurve as tuple
            abi.decode(utilizationCurveEncoded, (bytes))
        );

        // The above approach can't reliably match the complex ABI types. Use a safer route: craft calldata manually.
        // We'll ABI-encode the ProductInfo matching explicit types as a tuple.
        bytes memory fullProductInfo = abi.encode(
            string(name),
            string(symbol),
            // payoffDefinition as tuple (uint8,uint8,bytes30)
            (payoffType, payoffDirection, emptyPayoffData),
            oracleAddr,
            maintenance_val,
            fundingFee,
            makerFee,
            takerFee,
            positionFee,
            makerLimit,
            // JumpRateUtilizationCurve tuple: (uint256,uint256,uint256,uint256)
            (uint256(0), uint256(0), uint256(0), uint256(0))
        );

        // Now call initialize via function selector
        bytes4 selector = bytes4(keccak256("initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(uint256,uint256,uint256,uint256)))"));

        // low-level call to initialize on c
        (bool okInit,) = address(c).call(abi.encodeWithSelector(selector, abi.decode(fullProductInfo, (
            string,
            string,
            // payoffDefinition tuple type
            tuple(uint8,uint8,bytes30),
            address,
            uint256,
            uint256,
            uint256,
            uint256,
            uint256,
            uint256,
            tuple(uint256,uint256,uint256,uint256)
        ))));

        // If initialization failed (e.g., due to controller expectations), we cannot continue; assume success requirement for the property
        // The correct contract's initialize requires msg.sender to be controller; setUp used new C() so caller is this test contract, which will be treated as controller in __UControllerProvider__initialize.
        // If initialization reverted, treat as inadmissible input and return (property vacuously holds for only initialized cases). Use vm.assume to require success.
        vm.assume(okInit);

        // Now call maintenance(account) and record result
        bool okCall;
        uint256 returned;
        try c.maintenance(account) returns (uint256 v) {
            okCall = true;
            returned = v;
        } catch {
            okCall = false;
            returned = 0;
        }

        // For the reference, maintenance(account) should always return the per-product stored maintenance (the maintenance_val we encoded).
        // The mutant returns controller().minCollateral() instead, so when controller.minCollateral() != maintenance_val the mutant differs.
        // Assert that the observed maintenance equals the maintenance we initialized (productMaintenanceRaw).
        // This single assertion will hold for the reference for all inputs where initialization succeeded; the mutant will fail for some inputs where controller.minCollateral()!=maintenance_val.
        assertTrue(okCall && returned == maintenance_val);
    }
}

